#include <stdio.h>

int main(void)
{
    char s[105];
    int cnt[128] = {0};
    int i;

    scanf("%s", s);
    for (i = 0; s[i] != '\0'; i++) {
        cnt[(unsigned char)s[i]]++;
    }
    for (i = 0; i < 128; i++) {
        int isUpper = (i >= 'A' && i <= 'Z');
        int isLower = (i >= 'a' && i <= 'z');
        if ((isUpper || isLower) && cnt[i] > 0) {
            printf("The character %c has presented %d times.\n", i, cnt[i]);
        }
    }
    return 0;
}

#include <stdio.h>

#define N 1005

int main(void)
{
    int n, a[N];
    int i, cur = 1, best = 1;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    for (i = 1; i < n; i++) {
        if (a[i] == a[i - 1]) {
            cur++;
        } else {
            cur = 1;
        }
        if (cur > best) {
            best = cur;
        }
    }
    printf("%d\n", best);
    return 0;
}

