#include <stdio.h>

int main(void)
{
    char s[105];
    int i, depth = 0, ok = 1;

    scanf("%s", s);
    for (i = 0; s[i] != '\0'; i++) {
        if (s[i] == '(') {
            depth++;            /* 遇到左括号，层数加一 */
        } else if (s[i] == ')') {
            if (depth == 0) {   /* 没有对应的左括号 */
                ok = 0;
                break;
            }
            depth--;
        }
    }
    if (depth != 0) {           /* 还有左括号没被匹配 */
        ok = 0;
    }
    if (ok) {
        printf("parentheses match!\n");
    } else {
        printf("parentheses do not match!\n");
    }
    return 0;
}

#include <stdio.h>

#define N 1005

static void printArray(const int a[], int n)
{
    int i;
    for (i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", a[i]);
    }
    printf("\n");
}

int main(void)
{
    int n, a[N];
    int i, j, key;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    for (i = 1; i < n; i++) {      /* 第 i 趟：把 a[i] 插入前面有序段 */
        key = a[i];
        j = i - 1;
        while (j >= 0 && a[j] > key) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;
        printArray(a, n);          /* 每趟结束输出整个数组 */
    }
    return 0;
}

