int main(void)
{
    int n, a[N];
    int i, j, minIdx, t;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    for (i = 0; i < n - 1; i++) {          /* 第 i 趟：确定 a[i] 处的元素 */
        minIdx = i;
        for (j = i + 1; j < n; j++) {
            if (a[j] < a[minIdx]) {
                minIdx = j;
            }
        }
        if (minIdx != i) {
            t = a[i];
            a[i] = a[minIdx];
            a[minIdx] = t;
        }
        printArray(a, n);
    }
    return 0;
}

