            missing = i;
        }
    }
    printf("%d\n", duplicate);
    printf("%d\n", missing);
    return 0;
}

#include <stdio.h>

#define N 105

int main(void)
{
    int n, m, t, i;
    int b[N], half[N];

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &b[i]);
    }
    scanf("%d", &m);

    for (t = 0; t < m; t++) {
        for (i = 0; i < n; i++) {          /* 第一步：奇数补成偶数 */
            if (b[i] % 2 == 1) {
                b[i]++;
            }
        }
        for (i = 0; i < n; i++) {          /* 第二步：每人的一半 */
            half[i] = b[i] / 2;
        }
        for (i = 0; i < n; i++) {          /* 同时分给下一人，自己留一半 */
            b[i] = half[i] + half[(i - 1 + n) % n];
        }
    }

    for (i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", b[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

#define N 85

int main(void)
{
    int n, l, r, i;
    long long f[N], pref[N];

    scanf("%d%d%d", &n, &l, &r);

    f[1] = 1;
    f[2] = 1;
    for (i = 3; i <= n; i++) {
        f[i] = f[i - 1] + f[i - 2];
    }

    pref[0] = 0;
    for (i = 1; i <= n; i++) {
        pref[i] = pref[i - 1] + f[i];
    }

    printf("%lld\n", pref[n]);              /* 前 n 项之和 */
    printf("%lld\n", pref[r] - pref[l - 1]); /* 第 l 项到第 r 项之和 */
    return 0;
}

#include <stdio.h>

#define N 1005

int main(void)
{
    int n, m, i, remain, idx, count, first = 1, survivor = 0;
    int a[N];

    scanf("%d%d", &n, &m);
    for (i = 1; i <= n; i++) {
        a[i] = i;
    }

    remain = n;
    idx = 1;
    count = 0;
    while (remain > 1) {
        if (a[idx] != 0) {              /* 0 表示已经出圈 */
            count++;
            if (count == m) {
                if (!first) {
                    printf(" ");
                }
                printf("%d", a[idx]);
                first = 0;
                a[idx] = 0;
                count = 0;
                remain--;
            }
        }
        idx = idx % n + 1;              /* 移到下一个人，n 之后回到 1 */
    }
    for (i = 1; i <= n; i++) {
        if (a[i] != 0) {
            survivor = a[i];
            break;
        }
    }
    printf("\n%d\n", survivor);
    return 0;
}

#include <stdio.h>

#define N 1005

int main(void)
{
    int n, k, i, j, maxlen;
    long long a[N], pref[N];
    long long best = 0, sum;
    int has = 0;

    scanf("%d%d", &n, &k);
    for (i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
    }

    pref[0] = 0;
    for (i = 1; i <= n; i++) {
        pref[i] = pref[i - 1] + a[i];
    }

    for (i = 1; i <= n; i++) {              /* 枚举子段右端点 i */
        maxlen = (i < k) ? i : k;           /* 长度不超过 k，也不超过 i */
        for (j = 1; j <= maxlen; j++) {     /* 枚举长度 j */
            sum = pref[i] - pref[i - j];
            if (!has || sum > best) {
                best = sum;
                has = 1;
            }
        }
    }

    printf("%lld\n", best);
    return 0;
}

#include <stdio.h>

#define N 55

int main(void)
{
    int n, i, j, val = 1;
    int top, bottom, left, right;
    int a[N][N];

    scanf("%d", &n);
    top = 0;
    bottom = n - 1;
    left = 0;
    right = n - 1;

    while (top <= bottom && left <= right) {
        for (j = left; j <= right; j++) {          /* 从左到右 */
            a[top][j] = val++;
        }
        top++;
        for (i = top; i <= bottom; i++) {          /* 从上到下 */
            a[i][right] = val++;
        }
        right--;
        if (top <= bottom) {                       /* 从右到左 */
            for (j = right; j >= left; j--) {
                a[bottom][j] = val++;
            }
            bottom--;
        }
        if (left <= right) {                       /* 从下到上 */
            for (i = bottom; i >= top; i--) {
                a[i][left] = val++;
            }
            left++;
        }
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (j > 0) {
                printf(" ");
            }
            printf("%d", a[i][j]);
        }
        printf("\n");
    }
    return 0;
}
